#include <iostream>
#include <algorithm>
using namespace std;

long long total_steps = 0;

int get_digit_count(long long n) {
    int count = 0;
    while (n != 0) {
        n /= 10;
        count++;
    }
    return count;
}

long long compute_base(long long n) {
    int digits = get_digit_count(n);
    long long base = 0, power = 1;
    for (int i = 0; i < digits; i++) {
        base += power;
        power *= 10;
    }
    if (base <= n) return base;
    return (base - 1) / 10;
}

long long solve_number(long long n) {
    if (n <= 6) return n;
    if (n <= 11) return 13 - n;
    long long base_value = compute_base(n);
    long long boundary = base_value * 10 + 1;
    if (n % base_value == 0) {
        long long quotient = n / base_value;
        if (n <= boundary / 2 + base_value) return get_digit_count(base_value) * quotient;
        else {
            long long diff = solve_number(boundary - n);
            return get_digit_count(boundary) + diff;
        }
    } else {
        long long lower = (n / base_value) * base_value;
        long long upper = (n / base_value + 1) * base_value;
        long long total_res = solve_number(lower) + solve_number(n - lower);
        if (n > boundary / 2) {
            total_res = min(solve_number(lower) + solve_number(n - lower),
                            get_digit_count(boundary) + solve_number(boundary - n));
        }
        return total_res;
    }
}

int main() {
    long long n;
    cin >> n;
    cout << solve_number(n) << endl;
    return 0;
}
